const root="/home/axel/LeanAlgebraicGeometry-Horizon/.lake-packages/mathlib/Mathlib";
const cmds=[
`rg -n "det_ne_zero.*LinearIndependent|LinearIndependent.*det_ne_zero|det_eq_zero.*LinearDependent|det_ne_zero_iff" ${root}/LinearAlgebra/Matrix -g '*.lean' | head -n 160`,
`rg -n "rows.*LinearIndependent|linearIndependent_rows|rows_linearIndependent|vecMul.*injective" ${root}/LinearAlgebra/Matrix -g '*.lean' | head -n 180`,
`rg -n "basis.*matrix.*GeneralLinearGroup|toMatrix.*GeneralLinearGroup|mkOf.*LinearIndependent" ${root}/LinearAlgebra -g '*.lean' | head -n 180`
];
const rs=await Promise.all(cmds.map(cmd=>tools.exec_command({cmd,workdir:"/home/axel/LeanAlgebraicGeometry-Horizon",yield_time_ms:10000,max_output_tokens:14000})));
rs.forEach((r,i)=>text(`===${i+1}===\n${r.output}`));

const wd="/home/axel/LeanAlgebraicGeometry-Horizon/MainProjects/Algebraic-Jacobian-Challenge-Rebuild";
const cmds=[
"sed -n '1,280p' AlgebraicJacobian/Cohomology/TwistedFiberTwoCover.lean",
"sed -n '1,180p' AlgebraicJacobian/Picard/DivSchemeCertZarConfine.lean",
"rg -n \"relP1|relCurve.*P1|baseChange.*π|π.*baseChange|relMap|map.*relCurve|rel.*π\" AlgebraicJacobian -g '*.lean' | head -n 240",
"rg -n \"supportLocus.*Finite|Finite.*supportLocus|fibre.*support|support.*fibre\" AlgebraicJacobian/Picard -g '*.lean' | head -n 240"
];
const rs=await Promise.all(cmds.map(cmd=>tools.exec_command({cmd,workdir:wd,yield_time_ms:10000,max_output_tokens:22000})));
rs.forEach((r,i)=>text(`===${i+1}===\n${r.output}`));

const wd="/home/axel/LeanAlgebraicGeometry-Horizon/MainProjects/Algebraic-Jacobian-Challenge-Rebuild";
const cmds=[
"rg -n \"noncomputable def relCover|def relCover|relCover_V|relCover.*V₀|relCover.*V₁\" AlgebraicJacobian/Cohomology AlgebraicJacobian/Curve -g '*.lean' | head -n 180",
"rg -n \"def relCurve|noncomputable def relCurve|def fst|noncomputable def fst|baseChange.*left\" AlgebraicJacobian/Curve -g '*.lean' | head -n 200",
